<script setup>import {ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';import StatusTag from '../../components/StatusTag.vue';const message=ref('');const scan=valid=>{const r=actions.checkin(valid);message.value=r.message}</script>
<template><section class="h5-page"><div class="h5-module-hero"><span>卡</span><h2>模拟扫码打卡</h2><p>G2-FR-017—020、024</p></div><div v-if="message" class="action-message">{{message}}</div><div class="qr-placeholder">MOCK QR<br><small>东区展厅入口</small></div><div class="button-row"><button class="primary-button active" @click="scan(true)">模拟有效扫码</button><button class="secondary-button" @click="scan(false)">模拟超出范围</button></div>
<div class="h5-card"><header><strong>最近记录</strong><span>{{state.checkins.length}}</span></header><div v-for="row in state.checkins.slice(0,3)" :key="row.id" class="mini-row"><div><strong>{{row.point}}</strong><small>{{row.time}} · {{row.reason}}</small></div><StatusTag :text="row.status"/></div></div></section></template>